import{_ as a,o as e,c as s,a3 as o}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"经济与威望","description":"","frontmatter":{},"headers":[],"relativePath":"features/economy.md","filePath":"features/economy.md","lastUpdated":1791133906000}'),i={name:"features/economy.md"};function n(d,t,r,l,c,h){return e(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="经济与威望" tabindex="-1">经济与威望 <a class="header-anchor" href="#经济与威望" aria-label="Permalink to &quot;经济与威望&quot;">​</a></h1><p>威望（Renown）是《大西洋舰队》里的主要资源，用来买船、修船、解锁新内容。本篇讲怎么调节经济节奏。</p><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数键</th><th>默认</th><th>软边界</th><th>硬边界</th><th>说明</th></tr></thead><tbody><tr><td><code>economy.renownGainMul</code></td><td>1.0</td><td>0.5 – 5.0</td><td>0 – 100</td><td>威望获取倍率</td></tr><tr><td><code>repair.timeMul</code></td><td>1.0</td><td>0.5 – 2.0</td><td>0 – 5</td><td>玩家舰船修理时间倍率</td></tr><tr><td><code>sandbox.startRenown</code></td><td>0</td><td>0 – 100</td><td>0 – 500</td><td>新战役额外起始威望（千）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">术语：威望 = 威望 = Renown</p><p>游戏内这个词有时译作「威望」、有时「威望」，指的是同一个东西（<code>Renown</code>）。框架文档里统一用「威望」。</p></div><h2 id="三个参数分别管什么" tabindex="-1">三个参数分别管什么 <a class="header-anchor" href="#三个参数分别管什么" aria-label="Permalink to &quot;三个参数分别管什么&quot;">​</a></h2><h3 id="economy-renowngainmul-——-赚得快不快" tabindex="-1"><code>economy.renownGainMul</code> —— 赚得快不快 <a class="header-anchor" href="#economy-renowngainmul-——-赚得快不快" aria-label="Permalink to &quot;`economy.renownGainMul` —— 赚得快不快&quot;">​</a></h3><p>战斗胜利、完成任务获得的威望量。</p><ul><li><code>2.0</code> = 收入翻倍 → 攒舰队速度明显变快</li><li><code>5.0</code> = 五倍 → 基本不缺钱</li></ul><p><strong>这是长期节奏参数</strong>，适合想快点体验后期内容的人。</p><h3 id="repair-timemul-——-修船等多久" tabindex="-1"><code>repair.timeMul</code> —— 修船等多久 <a class="header-anchor" href="#repair-timemul-——-修船等多久" aria-label="Permalink to &quot;`repair.timeMul` —— 修船等多久&quot;">​</a></h3><p>受伤的船需要时间修理。这个值控制修理耗时。</p><ul><li><code>1.0</code> = 原版</li><li><code>0.5</code> = 修理时间减半</li><li><code>0</code> = <strong>立即修好</strong>（等同 <code>sandbox.instantRepair</code>）</li></ul><div class="tip custom-block"><p class="custom-block-title">想省事就调这个</p><p><code>repair.timeMul: 0</code> 是「修船不要等」的效果，比反复点「立即修理」舒服。而且它是<strong>持续性</strong>的，不用每次手动点。</p></div><h3 id="sandbox-startrenown-——-开局送多少" tabindex="-1"><code>sandbox.startRenown</code> —— 开局送多少 <a class="header-anchor" href="#sandbox-startrenown-——-开局送多少" aria-label="Permalink to &quot;`sandbox.startRenown` —— 开局送多少&quot;">​</a></h3><p><strong>开新战役时</strong>额外给的威望，单位是<strong>千</strong>。</p><table tabindex="0"><thead><tr><th>设定值</th><th>实际效果</th></tr></thead><tbody><tr><td><code>0</code></td><td>关闭（默认）</td></tr><tr><td><code>50</code></td><td>开局多 5 万威望</td></tr><tr><td><code>100</code></td><td>开局多 10 万威望</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">只对新战役生效</p><p>这个参数只在<strong>创建新战役</strong>时起作用。已有的存档不会因为你改了它就突然多一笔钱。</p><p>想在<strong>现有存档</strong>里加威望，去 <a href="/AtlanticFleetSite/docs/use/save-page">存档页</a> 直接改（那里是直接改当前战役的威望）。</p></div><h2 id="两套思路-调收益-vs-直接给钱" tabindex="-1">两套思路：调收益 vs 直接给钱 <a class="header-anchor" href="#两套思路-调收益-vs-直接给钱" aria-label="Permalink to &quot;两套思路：调收益 vs 直接给钱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>思路</th><th>用哪个</th><th>适合</th></tr></thead><tbody><tr><td><strong>慢慢变富</strong></td><td><code>economy.renownGainMul</code></td><td>想保留养成乐趣，只是不想太肝</td></tr><tr><td><strong>直接起飞</strong></td><td><code>sandbox.startRenown</code> + <a href="/AtlanticFleetSite/docs/use/save-page">存档页</a></td><td>想直接玩后期内容</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">推荐组合</p><p>如果你只是「不想太肝」，用这一套最舒服：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;轻松养成&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;economy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;renownGainMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;repair&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timeMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>收入翻 2.5 倍 + 修船时间减半。<strong>每天打两三局就能稳步推进</strong>，不会因为缺钱卡住，也不会因为钱太多失去目标感。</p></div><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">大倍数会让游戏失去挑战</p><p><code>renownGainMul</code> 调到 <code>10</code> 以上，你会很快买光所有船、修船不心疼，<strong>游戏的资源管理乐趣就没了</strong>。</p><p>建议先试 <code>2.0</code> – <code>3.0</code>，感觉还慢再往上加。这个参数随时可以改，不用一次到位。</p></div><h2 id="现有的存档怎么加威望" tabindex="-1">现有的存档怎么加威望 <a class="header-anchor" href="#现有的存档怎么加威望" aria-label="Permalink to &quot;现有的存档怎么加威望&quot;">​</a></h2><p><code>startRenown</code> 只对新战役生效。现有存档想加威望：</p><p>面板 → 「<strong>存档</strong>」页 → 用「威望」那一栏的加减按钮，或者一键设值。</p><p>那里改的是<strong>当前正在进行的战役</strong>，改完点「保存到存档」即可。详见 <a href="/AtlanticFleetSite/docs/use/save-page">存档页：改威望与回合</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>修理相关的另一个开关 → <a href="/AtlanticFleetSite/docs/features/sandbox">沙盒与调试开关</a></li><li>改现有存档的威望 → <a href="/AtlanticFleetSite/docs/use/save-page">存档页：改威望与回合</a></li><li>完整参数表 → <a href="/AtlanticFleetSite/docs/features/matrix">功能接入总表</a></li></ul>',29)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
